(7298566, 1138319, 177322, '<td valign="top">I like this:  compositionally, certainly plenty of artificial lighting, lots of lines to follow.  Good exposure in a challenging setting.  Good luck.</td>', 'I like this:  compositionally, certainly plenty of artificial lighting, lots of lines to follow.  Good exposure in a challenging setting.  Good luck.', '2015-01-04 11:06:55.000000', NULL, 1),
(7298570, 1137918, 177322, '<td valign="top">The vibrant intensity makes this image a standout in this challenge.  The leading line of the bridge lends to compositional strength.</td>', 'The vibrant intensity makes this image a standout in this challenge.  The leading line of the bridge lends to compositional strength.', '2015-01-04 11:08:57.000000', NULL, 1),
(7298574, 1138313, 177322, '<td valign="top">Whimsical indeed!  The daring tilt to the image lends to the constellation-like patterns of the "stars."  Quite engaging.  Best of luck.</td>', 'Whimsical indeed!  The daring tilt to the image lends to the constellation-like patterns of the "stars."  Quite engaging.  Best of luck.', '2015-01-04 11:11:58.000000', NULL, 1),
(7298575, 1138334, 177322, '<td valign="top">My inclination was to say, "This really pops," but actually it is the radiance that makes it such a stand out image in this challenge.  The reflections make it even stronger.  Nicely exposed.  Hoping for a ribbon for you on this one.</td>', 'My inclination was to say, "This really pops," but actually it is the radiance that makes it such a stand out image in this challenge.  The reflections make it even stronger.  Nicely exposed.  Hoping for a ribbon for you on this one.', '2015-01-04 11:15:32.000000', NULL, 1),
(7298688, 1138139, 179675, '<td valign="top">Really like the softness of this shot and the narrow depth of focus. You''ve not smoothed the skin out too much, which is easy to do.</td>', 'Really like the softness of this shot and the narrow depth of focus. You''ve not smoothed the skin out too much, which is easy to do.', '2015-01-04 19:10:25.000000', NULL, 1),
(7298690, 1138192, 179675, '<td valign="top">Very elegant portrait. Wish there was a little more light on her face to ensure it becomes the center of attention. Right now it''s competing with the wine glass for my focus. Beautifully done! 8</td>', 'Very elegant portrait. Wish there was a little more light on her face to ensure it becomes the center of attention. Right now it''s competing with the wine glass for my focus. Beautifully done! 8', '2015-01-04 19:11:28.000000', NULL, 1),
